// The three intent variants, from least to most given.
const (
	VariantBehaviour  Variant = "behaviour"
	VariantSignatures Variant = "signatures"
	VariantCode       Variant = "code"
)

// Variants returns every variant in order.
func Variants() []Variant {
	return []Variant{VariantBehaviour, VariantSignatures, VariantCode}
}

// Intent returns the task's intent text for v.
func (t Task) Intent(v Variant) (string, error) {
	switch v {
	case VariantBehaviour:
		return t.Behaviour, nil
	case VariantSignatures:
		return t.Signatures, nil
	case VariantCode:
		return t.Code, nil
	}
	return "", fmt.Errorf("unknown variant %q", v)
}

// Isolated returns an error when hidden test text could reach the model: a
// hidden file's name, or any of its "func Test" lines, appearing in any of the
// task's intents.
func (t Task) Isolated() error {
	for _, v := range Variants() {
		intent, err := t.Intent(v)
		if err != nil {
			return err
		}
		for _, f := range t.Hidden {
			if strings.Contains(intent, f) {
				return fmt.Errorf("task %s: the %s intent names hidden file %s", t.ID, v, f)
			}
			data, err := os.ReadFile(filepath.Join(t.Dir, "hidden", f))
			if err != nil {
				return err
			}
			for _, line := range strings.Split(string(data), "\n") {
				if strings.HasPrefix(line, "func Test") && strings.Contains(intent, line) {
					return fmt.Errorf("task %s: the %s intent contains the hidden test line %q", t.ID, v, line)
				}
			}
		}
	}
	return nil
}

func TestIntentVariants(t *testing.T) {
	task := Task{Behaviour: "b", Signatures: "s", Code: "c"}
	for v, want := range map[Variant]string{VariantBehaviour: "b", VariantSignatures: "s", VariantCode: "c"} {
		got, err := task.Intent(v)
		if err != nil || got != want {
			t.Errorf("Intent(%s) = %q, %v, want %q", v, got, err, want)
		}
	}
	if _, err := task.Intent("nope"); err == nil {
		t.Fatal("an unknown variant must be an error")
	}
	if got := Variants(); len(got) != 3 || got[0] != VariantBehaviour || got[2] != VariantCode {
		t.Fatalf("Variants() = %v", got)
	}
}

func TestIsolatedRealTasks(t *testing.T) {
	tasks, err := LoadTasks("testdata/tasks")
	if err != nil {
		t.Fatal(err)
	}
	for _, task := range tasks {
		if err := task.Isolated(); err != nil {
			t.Errorf("%s: %v", task.ID, err)
		}
	}
}

func TestIsolatedCatchesLeaks(t *testing.T) {
	root := t.TempDir()
	dir := writeTask(t, root, "ok", validTask)
	task, err := LoadTask(dir)
	if err != nil {
		t.Fatal(err)
	}
	if err := task.Isolated(); err != nil {
		t.Fatalf("a clean task: %v", err)
	}
	named := task
	named.Signatures = "see a_test.go"
	if err := named.Isolated(); err == nil || !strings.Contains(err.Error(), "a_test.go") {
		t.Fatalf("a named hidden file: %v", err)
	}
	leaked := task
	leaked.Behaviour = "copy this\nfunc TestA(t *testing.T) {}\n"
	if err := leaked.Isolated(); err == nil || !strings.Contains(err.Error(), "func TestA") {
		t.Fatalf("a leaked test line: %v", err)
	}
	if err := os.Remove(filepath.Join(dir, "hidden", "a_test.go")); err != nil {
		t.Fatal(err)
	}
	if err := task.Isolated(); err == nil {
		t.Fatal("an unreadable hidden file must be an error")
	}
}

